%% ========================================================================
%  REBUILD 3D SATELLITE SCENARIO VIEWER FROM CLUSTER DATA
%  Load simulation results and recreate interactive 3D visualization.
%
%  Compatible with: generate_flight_baseline.m  (flight_<run_id>.mat)
%
%  Prerequisites:
%    flight_<run_id>.mat    — generated by generate_flight_baseline.m
%    starlink.tle           — Starlink TLE file used during data generation
%    orbcomm.tle            — Orbcomm TLE file used during data generation
%    iridium.tle            — Iridium NEXT TLE file used during data generation
%    drone-1-waypoints.txt  — ATAK mission waypoints (lat,lon per line, '#' comments)
%% ========================================================================

clear; close all; clc;

fprintf('\n========================================\n');
fprintf('Rebuilding 3D Scenario from Cluster Data\n');
fprintf('========================================\n\n');

%% ========================================================================
%  CONFIGURATION — edit these to match your run
%% ========================================================================

run_id        = 1;            % run_id used when calling generate_flight_baseline
output_folder = 'C:\Users\junhy\mit\Codes\data_navigation_v1';     % folder where flight_<run_id>.mat was saved

% ── Flight trajectory from the .mat file ────────────────────────────────
% false → ignore the flight file's trajectory (flight_1.mat is a Boston
%         flight) and fly a drone along the drone-1 waypoints instead.
%         Only the flight file's start time is used.
% true  → plot the flight file's UAV trajectory and its satellites.
show_flight_trajectory = false;

% ── Mission waypoints ───────────────────────────────────────────────────
waypoint_file  = 'C:\Users\junhy\Team-13\drone-1-waypoints.txt';
waypoint_alt_m = [];          % [] → flight altitude profile (route below),
                              %      or nearest flight-file sample when the
                              %      trajectory is shown; or a scalar (m)
show_waypoint_map = true;     % also draw a 2-D geoplot of the route

% ── Drone flying the waypoints (when show_flight_trajectory = false) ────
% Vertical climb at TAKEOFF, waypoints flown in straight lines at
% route_alt_m, vertical descent at LANDING — all at route_speed_mps.
% The scenario is lengthened to cover the whole flight.
route_speed_mps = 10;         % m/s along the path
route_alt_m     = 100;        % m, cruise altitude (takeoff/landing at 0 m)
% Takeoff time. Set TimeZone to 'America/Los_Angeles' for local time at
% the route; [] → use the flight file's start time.
route_start_time = datetime(2026, 11, 8, 4, 47, 0, 'TimeZone', 'America/Los_Angeles');
                              % 04:47 PST: most usable Iridium sats on 8 Nov
                              % (sweep with the 13 May 2026 TLEs)

% ── Satellite selection when show_flight_trajectory = false ─────────────
% Satellites are chosen as visible from the drone-1 route (route centre),
% using the same rule as generate_synthetic_data.m: elevation ≥
% selection_mask_deg for at least min_visibility_sec of the scenario window.
% The same mask gates the yellow visibility lines to the drone.
show_constellations = {'Iridium'};   % any of 'Starlink','Orbcomm','Iridium'
include_all_sats    = true;   % true → every satellite of show_constellations,
                              %        visible or not (lines still only
                              %        appear while above the mask)
selection_mask_deg  = 10;     % deg (flight generator uses 20)
min_visibility_sec  = 200;    % generate_synthetic_data.m default

% ── Satellites to label (one per constellation) ─────────────────────────
% Leave a field empty to auto-pick the first satellite of that constellation
% in the selected set, or put an exact TLE name (e.g. 'STARLINK-32558').
% If the requested/needed satellite is not in the selected set, it is added
% from its TLE file (display only — not included in the access analysis).
label_sat_override = struct( ...
    'Starlink', '', ...
    'Orbcomm',  '', ...
    'Iridium',  '');
label_all_sats = true;        % true → label every satellite in the scenario
                              %        (not just one per constellation)

%% ========================================================================
%  LOAD CLUSTER DATA
%% ========================================================================

fprintf('Loading simulation data from cluster...\n');

data_filepath = sprintf('%s/flight_%d.mat', output_folder, run_id);
if ~exist(data_filepath, 'file')
    error(['Data file not found: %s\n' ...
           'Set run_id and output_folder at the top of this script\n' ...
           'to match the values used when running generate_flight_baseline.'], ...
           data_filepath);
end

load(data_filepath);

% ── Derived convenience variables ────────────────────────────────────────
% sat_time_array  : datetime array at satellite rate (1 Hz)
% num_selected_sats: number of visible LEO satellites selected by filter
% uav_lat_deg / uav_lon_deg / uav_alt_m : 1-Hz UAV trajectory
% sat_update_step_sec : scenario time step (seconds)
% mode_sequence_sat   : SLDS mode index at 1 Hz
% min_elevation_deg   : elevation mask angle (deg)
% ground_truth.satellites(s).Name : satellite names

scenario_start_time = sat_time_array(1);
scenario_stop_time  = sat_time_array(end);

fprintf('✓ Loaded data:\n');
fprintf('  Trajectory  : %d timesteps @ %g Hz\n', ...
    num_sat_steps, 1/sat_update_step_sec);
fprintf('  Satellites  : %d visible\n', num_selected_sats);
fprintf('  Duration    : %.1f seconds\n', ...
    seconds(scenario_stop_time - scenario_start_time));

%% ========================================================================
%  CHECK FOR TLE FILES
%% ========================================================================

fprintf('\nChecking for TLE files...\n');

tle_files      = {'starlink.tle', 'orbcomm.tle', 'iridium.tle'};
constellations = {'Starlink',     'Orbcomm',     'Iridium'};   % same order

for k = 1:numel(tle_files)
    if ~exist(tle_files{k}, 'file')
        error(['TLE file not found: %s\n' ...
               'Copy the same TLE files used on the cluster to the\n' ...
               'current directory, or download fresh TLEs from:\n' ...
               '  https://celestrak.org/NORAD/elements/'], tle_files{k});
    end
    fprintf('  ✓ %s\n', tle_files{k});
end

%% ========================================================================
%  LOAD MISSION WAYPOINTS AND BUILD THE TIMED ROUTE
%% ========================================================================

fprintf('\nLoading mission waypoints...\n');

if ~exist(waypoint_file, 'file')
    error('Waypoint file not found: %s', waypoint_file);
end
fid = fopen(waypoint_file, 'r');
wp_raw = textscan(fid, '%f %f', 'Delimiter', ',', 'CommentStyle', '#');
fclose(fid);
wp_lat = wp_raw{1};
wp_lon = wp_raw{2};
keep   = ~isnan(wp_lat) & ~isnan(wp_lon);
wp_lat = wp_lat(keep);
wp_lon = wp_lon(keep);
num_wp = numel(wp_lat);

% Altitude profile: 0 m at TAKEOFF and LANDING, route_alt_m in between
wp_route_alt = repmat(route_alt_m, num_wp, 1);
wp_route_alt([1 end]) = 0;

if show_flight_trajectory
    scenario_time_array = sat_time_array;
else
    % Straight 3-D legs at constant speed; repeated points are dropped so
    % arrival times stay strictly increasing.
    seg_len = leg_lengths_m(wp_lat, wp_lon, wp_route_alt);
    keep_pt = [true; seg_len > 0.01];
    r_lat   = wp_lat(keep_pt);
    r_lon   = wp_lon(keep_pt);
    r_alt   = wp_route_alt(keep_pt);
    r_toa   = [0; cumsum(leg_lengths_m(r_lat, r_lon, r_alt)) / route_speed_mps];

    % 1-Hz samples along the straight legs (keeps the path on the legs —
    % geoTrajectory would otherwise round off the 90° corners)
    % plus the exact waypoint arrival times so every corner is hit
    route_duration_sec = ceil(r_toa(end));
    route_t   = unique([(0:route_duration_sec)'; r_toa]);
    route_lat = interp1(r_toa, r_lat, route_t, 'linear', r_lat(end));
    route_lon = interp1(r_toa, r_lon, route_t, 'linear', r_lon(end));
    route_alt = interp1(r_toa, r_alt, route_t, 'linear', r_alt(end));

    if ~isempty(route_start_time)
        % satelliteScenario works in UTC with time-zone-free datetimes
        t0 = route_start_time;
        if isempty(t0.TimeZone), t0.TimeZone = 'UTC'; end
        t0.TimeZone = 'UTC';
        t0.TimeZone = '';
        scenario_start_time = t0;
    end
    scenario_stop_time  = scenario_start_time + seconds(route_duration_sec);
    scenario_time_array = scenario_start_time + seconds(0:route_duration_sec);

    fprintf('✓ %d waypoints, %.2f km flown at %g m/s → %.1f min flight\n', ...
        num_wp, sum(leg_lengths_m(r_lat, r_lon, r_alt)) / 1000, ...
        route_speed_mps, r_toa(end) / 60);
end

%% ========================================================================
%  RECREATE SATELLITE SCENARIO
%% ========================================================================

fprintf('\nRecreating satellite scenario...\n');

sc = satelliteScenario(scenario_start_time, scenario_stop_time, ...
                       sat_update_step_sec);
fprintf('  Window: %s → %s\n', string(scenario_start_time), string(scenario_stop_time));

%% ── Extract TLEs for the selected satellites only ────────────────────────
%
%  generate_flight_baseline selected num_selected_sats from the full
%  Starlink / Orbcomm / Iridium constellation.  Each TLE file is parsed on
%  its own (so a stray blank line in one file cannot misalign the others),
%  and every entry remembers which constellation it came from.

tle_catalog = struct('name', {}, 'line1', {}, 'line2', {}, 'constellation', {});
for k = 1:numel(tle_files)
    entries = read_tle_file(tle_files{k});
    if isempty(entries)
        warning('No TLE entries parsed from %s.', tle_files{k});
        continue;
    end
    [entries.constellation] = deal(constellations{k});
    tle_catalog = [tle_catalog, entries]; %#ok<AGROW>
end
catalog_names = {tle_catalog.name};

if show_flight_trajectory
    % Satellites selected by the flight generator for this trajectory
    sat_names = cellfun(@(n) strtrim(char(n)), {ground_truth.satellites.Name}, ...
                        'UniformOutput', false);
else
    % Satellites visible from the drone-1 route over the flight window
    % (always computed, so the console reports which ones are usable)
    centre_lat = mean(wp_lat);
    centre_lon = mean(wp_lon);
    fprintf('Selecting satellites visible from the drone-1 route (%.4f, %.4f)...\n', ...
        centre_lat, centre_lon);
    shown_files = tle_files(ismember(constellations, show_constellations));
    [sat_names, vis_sec] = select_visible_sats(shown_files, scenario_time_array, ...
        centre_lat, centre_lon, route_alt_m, selection_mask_deg, min_visibility_sec);
    num_selected_sats = numel(sat_names);
    fprintf('  %d %s satellites above %g° for ≥ %d s: %s\n', num_selected_sats, ...
        strjoin(show_constellations, '/'), selection_mask_deg, min_visibility_sec, ...
        strjoin(sat_names, ', '));

    if include_all_sats
        shown = ismember({tle_catalog.constellation}, show_constellations);
        sat_names = catalog_names(shown);
        num_selected_sats = numel(sat_names);
        fprintf('  Adding all %d %s satellites (include_all_sats = true)\n', ...
            num_selected_sats, strjoin(show_constellations, '/'));
    end
end

% Match each selected satellite name to its TLE entry.
temp_tle = 'temp_rebuild.tle';
fid = fopen(temp_tle, 'w');
sat_constellation = {};          % constellation of sats(i), same order
num_skipped = 0;                 % matched, but constellation not shown

for s = 1:num_selected_sats
    j = find(strcmp(catalog_names, sat_names{s}), 1);
    if isempty(j)
        continue;
    end
    if ~ismember(tle_catalog(j).constellation, show_constellations)
        num_skipped = num_skipped + 1;
        continue;
    end
    fprintf(fid, '%s\n%s\n%s\n', tle_catalog(j).name, ...
            tle_catalog(j).line1, tle_catalog(j).line2);
    sat_constellation{end+1} = tle_catalog(j).constellation; %#ok<SAGROW>
end
fclose(fid);
found_count = numel(sat_constellation);

if found_count + num_skipped < num_selected_sats
    warning('Only found %d / %d satellites in TLE files.', ...
        found_count, num_selected_sats);
end

sats = satellite(sc, temp_tle);
delete(temp_tle);

fprintf('✓ Added %d satellites to scenario\n', numel(sats));

%% ========================================================================
%  PICK ONE STARLINK / ORBCOMM / IRIDIUM SATELLITE TO LABEL
%% ========================================================================

fprintf('\nSelecting satellites to label...\n');

label_colors = struct( ...
    'Starlink', [0.55 0.80 1.00], ...   % light blue
    'Orbcomm',  [0.20 1.00 0.40], ...   % green
    'Iridium',  [1.00 0.45 0.45]);      % salmon

scenario_sat_names = arrayfun(@(h) strtrim(char(h.Name)), sats, ...
                              'UniformOutput', false);

label_sats = {};                 % satellite handles to label after viewer
for c = 1:numel(show_constellations)
    cname     = show_constellations{c};
    requested = strtrim(label_sat_override.(cname));

    % 1) explicit name in selected set, or 2) first of this constellation
    if ~isempty(requested)
        idx = find(strcmp(scenario_sat_names, requested), 1);
    else
        idx = find(strcmp(sat_constellation, cname), 1);
    end

    if ~isempty(idx)
        h = sats(idx);
        note = 'in selected set';
    else
        % 3) not in the selected set → add it from its TLE file for display
        if ~isempty(requested)
            j = find(strcmp(catalog_names, requested), 1);
        else
            j = find(strcmp({tle_catalog.constellation}, cname), 1);
        end
        if isempty(j)
            warning('No %s satellite found to label (requested: "%s").', ...
                cname, requested);
            continue;
        end
        extra_tle = 'temp_label.tle';
        fid = fopen(extra_tle, 'w');
        fprintf(fid, '%s\n%s\n%s\n', tle_catalog(j).name, ...
                tle_catalog(j).line1, tle_catalog(j).line2);
        fclose(fid);
        h = satellite(sc, extra_tle);
        delete(extra_tle);
        note = 'NOT in selected set — added for display only';
    end

    h.MarkerColor    = label_colors.(cname);
    h.MarkerSize     = 12;
    h.LabelFontColor = label_colors.(cname);
    h.LabelFontSize  = 14;
    label_sats{end+1} = h; %#ok<SAGROW>

    fprintf('  %-8s → %s  (%s)\n', cname, strtrim(char(h.Name)), note);
end

if label_all_sats
    labelled_names = cellfun(@(h) strtrim(char(h.Name)), label_sats, ...
                             'UniformOutput', false);
    for i = 1:numel(sats)
        if ismember(scenario_sat_names{i}, labelled_names)
            continue;
        end
        h = sats(i);
        h.MarkerColor    = label_colors.(sat_constellation{i});
        h.MarkerSize     = 12;
        h.LabelFontColor = label_colors.(sat_constellation{i});
        h.LabelFontSize  = 14;
        label_sats{end+1} = h; %#ok<SAGROW>
    end
    fprintf('  Labelling all %d satellites in the scenario\n', numel(label_sats));
end

%% ========================================================================
%  ADD UAV PLATFORM WITH TRAJECTORY
%% ========================================================================

uav_lat = ground_truth.uav_lat_deg(:);
uav_lon = ground_truth.uav_lon_deg(:);
uav_alt = ground_truth.uav_alt_m(:);

if show_flight_trajectory
    fprintf('\nAdding UAV trajectory...\n');

    % sat_time_array is a datetime array; geoTrajectory expects elapsed seconds.
    sat_time_elapsed_sec = seconds(sat_time_array - scenario_start_time);

    uav_waypoints_deg_m = [uav_lat, uav_lon, uav_alt];
    uav_traj = geoTrajectory(uav_waypoints_deg_m, sat_time_elapsed_sec);

    uav = platform(sc, uav_traj, 'Name', 'UAV');
    uav.MarkerColor = 'cyan';
    uav.LabelFontColor = 'cyan';

    fprintf('✓ UAV platform created\n');
else
    fprintf('\nAdding drone-1 flying the waypoints...\n');

    uav_traj = geoTrajectory([route_lat, route_lon, route_alt], route_t);

    uav = platform(sc, uav_traj, 'Name', 'drone-1');
    uav.MarkerColor    = 'cyan';
    uav.LabelFontColor = 'cyan';

    fprintf('✓ drone-1 platform created (%d s, %g m/s, %g m cruise)\n', ...
        route_duration_sec, route_speed_mps, route_alt_m);
end

% Trajectory line (whole flight path, drawn in 3-D at flight altitude).
% Switched on after the viewer opens — ShowDetails = false hides it.
uav.Path.LineColor = [0 1 1];     % cyan, same as the drone marker
uav.Path.LineWidth = 2;

%% ========================================================================
%  ADD TRAJECTORY TRAIL (breadcrumb markers coloured by SLDS mode)
%% ========================================================================

% fprintf('Adding trajectory trail...\n');
%
% % Mode colours must match generate_flight_baseline.m flight_modes definitions:
% %   Mode 1 — Hover       → green
% %   Mode 2 — Cruise      → blue
% %   Mode 3 — Maneuver     → red
% mode_colors = {'green', 'blue', 'red'};
%
% trail_spacing  = 2;    % place a marker every N 1-Hz timesteps
%                        % (tight enough that short 1-10 s hovers still get a
%                        %  breadcrumb; set to 1 to guarantee every hover)
% trail_indices  = 1 : trail_spacing : num_sat_steps;
%
% for i = 1:length(trail_indices)
%     t_idx   = trail_indices(i);
%     mode_id = mode_sequence_sat(t_idx);   % 1-Hz mode label
%
%     gs = groundStation(sc, ...
%         ground_truth.uav_lat_deg(t_idx), ...
%         ground_truth.uav_lon_deg(t_idx), ...
%         'Altitude', ground_truth.uav_alt_m(t_idx), ...
%         'Name',     sprintf('Trail_%d', i));
%
%     if mode_id >= 1 && mode_id <= 3
%         gs.MarkerColor = mode_colors{mode_id};
%     else
%         gs.MarkerColor = 'white';
%     end
% end
%
% fprintf('  Added %d trail markers\n', length(trail_indices));
% fprintf('  Trail colour legend:\n');
% fprintf('    Green  = Mode 1 (Hover)\n');
% fprintf('    Blue   = Mode 2 (Cruise)\n');
% fprintf('    Red    = Mode 3 (Maneuver)\n');

%% ========================================================================
%  ADD MISSION WAYPOINTS
%% ========================================================================
%  One small orange marker per ATAK waypoint, in flying order. The takeoff
%  (first) and landing (last) waypoints are drawn larger in their own
%  colours. The file has no altitude column, so markers sit on the drone's
%  altitude profile (or the nearest flight-file sample / waypoint_alt_m).

fprintf('\nAdding mission waypoint markers...\n');

% Altitude + horizontal offset to the nearest flight-file trajectory sample
wp_alt       = wp_route_alt;
wp_offset_m  = zeros(num_wp, 1);
for w = 1:num_wp
    dN = (uav_lat - wp_lat(w)) * 111320;
    dE = (uav_lon - wp_lon(w)) * 111320 * cosd(wp_lat(w));
    [d2, nearest] = min(dN.^2 + dE.^2);
    wp_offset_m(w) = sqrt(d2);
    if show_flight_trajectory
        wp_alt(w) = uav_alt(nearest);
    end
end
if ~isempty(waypoint_alt_m)
    wp_alt(:) = waypoint_alt_m;
end

wp_color_route   = [1.0 0.55 0.0];   % orange
wp_color_takeoff = [0.0 1.00 0.0];   % green
wp_color_landing = [1.0 0.00 1.0];   % magenta

for w = 1:num_wp
    if w == 1
        wp_name = 'TAKEOFF';  wp_color = wp_color_takeoff;  wp_size = 10;
    elseif w == num_wp
        wp_name = 'LANDING';  wp_color = wp_color_landing;  wp_size = 10;
    else
        wp_name = sprintf('WP%02d', w);  wp_color = wp_color_route;  wp_size = 6;
    end
    gs = groundStation(sc, wp_lat(w), wp_lon(w), ...
        'Altitude', wp_alt(w), 'Name', wp_name);
    gs.MarkerColor = wp_color;
    gs.MarkerSize  = wp_size;
end

wp_dN = diff(wp_lat) * 111320;
wp_dE = diff(wp_lon) .* 111320 .* cosd(wp_lat(1:end-1));
fprintf('✓ Added %d waypoints (%.2f km horizontal path)\n', ...
    num_wp, sum(hypot(wp_dN, wp_dE)) / 1000);
if show_flight_trajectory && max(wp_offset_m) > 200
    warning(['Waypoints are up to %.0f m from the loaded UAV trajectory — ' ...
             'check that flight_%d.mat is the drone-1 flight.'], ...
             max(wp_offset_m), run_id);
end

%% ========================================================================
%  MARK START POINT
%% ========================================================================
%  Oversized white marker at the first trajectory point. Its label is
%  switched on after the viewer is created (ShowDetails = false hides
%  every label at viewer creation).

if show_flight_trajectory
    fprintf('\nMarking start point...\n');

    start_idx  = 1;
    finish_idx = num_sat_steps;

    start_gs = groundStation(sc, uav_lat(start_idx), uav_lon(start_idx), ...
        'Altitude', uav_alt(start_idx), 'Name', 'START');
    start_gs.MarkerColor    = [1 1 1];     % white
    start_gs.MarkerSize     = 10;
    start_gs.LabelFontColor = [1 1 1];

    fprintf('  START  @ (%.5f, %.5f)  → white marker\n', ...
        uav_lat(start_idx),  uav_lon(start_idx));
    fprintf('  (trajectory end @ (%.5f, %.5f))\n', ...
        uav_lat(finish_idx), uav_lon(finish_idx));
end

%% ========================================================================
%  ADD CONICAL SENSOR FOR ELEVATION-MASK FIELD OF VIEW
%% ========================================================================
if show_flight_trajectory
    mask_deg = min_elevation_deg;      % mask used by the flight generator
else
    mask_deg = selection_mask_deg;
end

fprintf('\nAdding elevation-mask sensor field of view...\n');
% The conical half-angle equals the complement of the elevation mask so
% that the cone boundary exactly matches the mask_deg horizon.
conical_fov_deg = 2 * (90 - mask_deg);

uav_sensor = conicalSensor(uav, ...
    'MaxViewAngle', conical_fov_deg, ...
    'Name', 'ElevationMask', ...
    'MountingAngles', [0; 180; 0]);   % point nadir → sky-facing cone

fprintf('✓ Sensor added (elevation mask: %g°, cone angle: %.0f°)\n', ...
    mask_deg, conical_fov_deg);

%% ========================================================================
%  COMPUTE SATELLITE ACCESS (yellow visibility lines)
%% ========================================================================

fprintf('\nComputing satellite access...\n');

ac = access(sats, uav_sensor);
ac.LineColor = 'yellow';

fprintf('✓ Visibility lines added for %d satellites\n', numel(sats));

%% ========================================================================
%  LAUNCH 3D VISUALIZATION
%% ========================================================================

fprintf('\nLaunching 3D Satellite Scenario Viewer...\n');

v = satelliteScenarioViewer(sc, 'ShowDetails', false);
% fieldOfView(uav_sensor);

% ShowDetails = false hides all labels when the viewer opens, so turn the
% wanted labels back on afterwards: one sat per constellation + START.
for i = 1:numel(label_sats)
    show_asset_label(label_sats{i});
end
if show_flight_trajectory
    show_asset_label(start_gs);
end
uav.Path.VisibilityMode = 'manual';   % stop following ShowDetails = false
show(uav.Path, v);                    % cyan trajectory line

%% ========================================================================
%  2-D WAYPOINT MAP
%% ========================================================================

if show_waypoint_map
    figure('Name', 'drone-1 mission waypoints', 'Color', 'w');
    gx = geoaxes;
    try
        geobasemap(gx, 'satellite');      % needs internet; falls back otherwise
    catch
    end
    hold(gx, 'on');
    if show_flight_trajectory
        geoplot(gx, uav_lat, uav_lon, '-', 'Color', [0 0.75 0.75], ...
            'LineWidth', 1.0, 'DisplayName', 'UAV trajectory (flight file)');
    end
    geoplot(gx, wp_lat, wp_lon, '-o', 'Color', wp_color_route, ...
        'MarkerFaceColor', wp_color_route, 'MarkerSize', 4, ...
        'LineWidth', 1.5, 'DisplayName', 'Mission waypoints');
    geoplot(gx, wp_lat(1), wp_lon(1), '^', 'MarkerSize', 10, ...
        'MarkerFaceColor', wp_color_takeoff, 'MarkerEdgeColor', 'k', ...
        'DisplayName', 'Takeoff');
    geoplot(gx, wp_lat(end), wp_lon(end), 'v', 'MarkerSize', 10, ...
        'MarkerFaceColor', wp_color_landing, 'MarkerEdgeColor', 'k', ...
        'DisplayName', 'Landing');
    hold(gx, 'off');
    legend(gx, 'Location', 'best');
    title(gx, sprintf('drone-1 mission: %d waypoints', num_wp));
end

fprintf('\n========================================\n');
fprintf('3D Visualization Ready!\n');
fprintf('========================================\n\n');

fprintf('Controls:\n');
fprintf('  ▶  Play   : Animate the scenario\n');
