%% ========================================================================
%  LOCAL FUNCTIONS
%% ========================================================================

function entries = read_tle_file(fname)
% Parse a 3-line TLE file into a struct array with name/line1/line2.
% Robust to blank lines and stray whitespace.
    lines = strtrim(splitlines(string(fileread(fname))));
    lines = cellstr(lines(lines ~= ""));
    entries = struct('name', {}, 'line1', {}, 'line2', {});
    k = 1;
    while k <= numel(lines) - 2
        if startsWith(lines{k+1}, '1 ') && startsWith(lines{k+2}, '2 ')
            entries(end+1) = struct('name',  lines{k}, ...
                                    'line1', lines{k+1}, ...
                                    'line2', lines{k+2}); %#ok<AGROW>
            k = k + 3;
        else
            k = k + 1;
        end
    end
end

function [names, vis_sec] = select_visible_sats(tle_files, t, lat0, lon0, h0, mask_deg, min_vis_sec)
% Names of satellites (from all TLE files) above mask_deg as seen from a
% fixed site for at least min_vis_sec over the datetime vector t (uniform
% step). SGP4 via propagateOrbit; decayed satellites are skipped.
    step_sec = seconds(t(2) - t(1));

    % Site position (WGS84) and local "up" unit vector, ECEF
    a = 6378137.0;  e2 = 6.69437999014e-3;
    N = a / sqrt(1 - e2 * sind(lat0)^2);
    site = [(N + h0) * cosd(lat0) * cosd(lon0);
            (N + h0) * cosd(lat0) * sind(lon0);
            (N * (1 - e2) + h0) * sind(lat0)];
    up   = [cosd(lat0) * cosd(lon0); cosd(lat0) * sind(lon0); sind(lat0)];

    names = {};  vis_sec = [];
    chunk = 500;
    for k = 1:numel(tle_files)
        tles = tleread(tle_files{k});
        for c0 = 1:chunk:numel(tles)
            idx = c0 : min(c0 + chunk - 1, numel(tles));
            P   = propagate_skip_decayed(t, tles(idx));     % 3 x nT x nSat
            rel = P - site;                                 % implicit expansion
            rng = sqrt(sum(rel.^2, 1));
            el  = asind(sum(rel .* up, 1) ./ rng);          % 1 x nT x nSat
            dur = squeeze(sum(el >= mask_deg, 2)) * step_sec;
            dur = dur(:);
            sel = find(dur >= min_vis_sec);
            names   = [names, arrayfun(@(i) strtrim(char(tles(idx(i)).Name)), ...
                                       sel(:)', 'UniformOutput', false)]; %#ok<AGROW>
            vis_sec = [vis_sec; dur(sel)]; %#ok<AGROW>
        end
    end
end

function P = propagate_skip_decayed(t, tles)
% propagateOrbit in the Earth-fixed frame; satellites that SGP4 reports
% as decayed get NaN positions instead of aborting the whole batch.
    try
        P = propagateOrbit(t, tles, 'OutputCoordinateFrame', 'fixed-frame');
        P = reshape(P, 3, numel(t), numel(tles));
    catch
        if isscalar(tles)
            P = nan(3, numel(t), 1);
        else
            half = floor(numel(tles) / 2);
            P = cat(3, propagate_skip_decayed(t, tles(1:half)), ...
                       propagate_skip_decayed(t, tles(half+1:end)));
        end
    end
end

function d = leg_lengths_m(lat, lon, alt)
% 3-D length (m) of each leg between consecutive points (flat-earth,
% fine over a few km).
    dN = diff(lat) * 111320;
    dE = diff(lon) .* 111320 .* cosd(lat(1:end-1));
    dU = diff(alt);
    d  = sqrt(dN.^2 + dE.^2 + dU.^2);
end

function show_asset_label(h)
% Turn on one asset's label in the viewer (needs R2022a+ for ShowLabel).
    if isprop(h, 'ShowLabel')
        h.ShowLabel = true;
    else
        warning('This MATLAB release has no ShowLabel property; label for "%s" not shown.', ...
            char(h.Name));
    end
end
